def lookup(table_no, raw_value):
    """Convert raw byte value to UI display value via lookup table."""
    table = FX_DATA_TABLES.get(table_no)
    if not table:
        return str(raw_value)
    return table['data'].get(raw_value, str(raw_value))


def get_table_name(table_no):
    """Returns display name for a table number."""
    table = FX_DATA_TABLES.get(table_no)
    return table['name'] if table else f'Table #{table_no}'


def reverse_lookup(table_no, ui_value):
    """Find raw value matching a UI value (best-effort, exact match only)."""
    table = FX_DATA_TABLES.get(table_no)
    if not table:
        return None
    for raw, val in table['data'].items():
        if val == ui_value or str(val) == str(ui_value):
            return raw
    return None


if __name__ == '__main__':
    print(f"Total tables: {len(FX_DATA_TABLES)}")
    total_rows = sum(len(t['data']) for t in FX_DATA_TABLES.values())
    print(f"Total rows: {total_rows}")
    
    print("\nTable #1 (LFO Frequency) sample:")
    t1 = FX_DATA_TABLES[1]['data']
    for k in [0, 1, 64, 127]:
        if k in t1:
            print(f"  {k} → {t1[k]}")
